    Invoke-Command -Session $session -ArgumentList $stage,$task,$wrapperPin -ScriptBlock {param($Stage,$Task,$Pin);$ErrorActionPreference='Stop';$path=Join-Path $Stage 'wrapper.ps1';if((Get-FileHash -LiteralPath $path).Hash.ToLowerInvariant() -cne $Pin -or (Get-ScheduledTask -TaskName $Task -ErrorAction SilentlyContinue)){throw 'Fresh pinned mutation wrapper required.'};Register-ScheduledTask -TaskName $Task -Action (New-ScheduledTaskAction -Execute "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" -Argument ('-NoProfile -NonInteractive -ExecutionPolicy Bypass -File "'+$path+'"')) -Principal (New-ScheduledTaskPrincipal -UserId SYSTEM -LogonType ServiceAccount -RunLevel Highest) -Settings (New-ScheduledTaskSettingsSet -ExecutionTimeLimit ([TimeSpan]::Zero))|Out-Null}
    Host-Guard;Invoke-Command -Session $session -ArgumentList $stage,$task,$wrapperPin -ScriptBlock {param($Stage,$Task,$Pin);$ErrorActionPreference='Stop';$t=Get-ScheduledTask -TaskName $Task;$i=Get-ScheduledTaskInfo -TaskName $Task;$path=Join-Path $Stage 'wrapper.ps1';if($t.State.ToString() -cne 'Ready' -or $i.LastRunTime.Year -ge 2000 -or $t.Principal.UserId -notin @('SYSTEM','S-1-5-18') -or $t.Principal.RunLevel.ToString() -cne 'Highest' -or (Get-FileHash -LiteralPath $path).Hash.ToLowerInvariant() -cne $Pin -or @(Get-ScheduledTask|Where-Object {$_.TaskName -like 'N2R-*' -and $_.State.ToString() -notin @('Ready','Disabled')}).Count){throw 'Only the fresh SYSTEM mutation task may start once.'};Start-ScheduledTask -TaskName $Task};Save 'start.json' @{start_issued_once=$true;expected_exit=0;completion_inferred=$false;utc=[DateTime]::UtcNow.ToString('o')};Get-Content -LiteralPath (Join-Path $root 'dispatch.json') -Raw
}catch{Save 'dispatch-failed.json' @{success=$false;run_id=$run;error=$_.Exception.ToString();automatic_retry=$false;completion_inferred=$false;utc=[DateTime]::UtcNow.ToString('o')};throw}
finally{if($null -ne $session){Remove-PSSession $session}}
